<?php
namespace ProjectPress\Admin\Manager\ProjectManager;
use ProjectPress\Includes\Core\Defaults;
use ProjectPress\Includes\Functions\Helpers\FormFieldHelper;
use ProjectPress\Includes\Functions\Helpers\RequestHelper;
use ProjectPress\Includes\Pages\Taxonomies;
use ProjectPress\Includes\Project\Core\Project;
use ProjectPress\Includes\Project\Core\ProjectClassificationRepository;
use ProjectPress\Includes\Project\ProjectManager as DomainProjectManager;
if(!defined('ABSPATH')){exit;}
final class Projects{
 private DomainProjectManager $manager; private ProjectClassificationRepository $classifications;
 public function __construct(DomainProjectManager $manager){$this->manager=$manager;$this->classifications=new ProjectClassificationRepository();}
 public function render():void{$args=array('status'=>RequestHelper::get_key('status',''),'priority'=>RequestHelper::get_key('priority',''),'visibility'=>RequestHelper::get_key('visibility',''),'search'=>RequestHelper::get_text('s',''),'page'=>max(1,RequestHelper::get_integer('paged',1)),'per_page'=>20);$projects=$this->manager->query($args);$new=admin_url('admin.php?page=projectpress&group=project-manager&tab=new');?><div class="d-flex justify-content-between align-items-center mb-3"><p class="text-secondary mb-0"><?php esc_html_e('Manage projects across ProjectPress.','projectpress');?></p><?php if(current_user_can('manage_options')||current_user_can('projectpress_projects_create')):?><a class="btn btn-primary" href="<?php echo esc_url($new);?>"><?php esc_html_e('New Project','projectpress');?></a><?php endif;?></div><form method="get" class="card card-body mb-3"><input type="hidden" name="page" value="projectpress"/><input type="hidden" name="group" value="project-manager"/><input type="hidden" name="tab" value="projects"/><div class="row g-2"><div class="col-md-5"><?php echo FormFieldHelper::text_input('s',$args['search'],array('placeholder'=>__('Search projects','projectpress')));?></div><div class="col-md-2"><?php echo FormFieldHelper::select('status',array_combine(Defaults::project_statuses(),array_map('ucwords',array_map(static fn($v)=>str_replace('_',' ',$v),Defaults::project_statuses()))),$args['status']);?></div><div class="col-md-2"><?php echo FormFieldHelper::select('priority',array_combine(Defaults::project_priorities(),array_map('ucwords',Defaults::project_priorities())),$args['priority']);?></div><div class="col-md-2"><?php echo FormFieldHelper::select('visibility',array_combine(Defaults::project_visibilities(),array_map('ucwords',Defaults::project_visibilities())),$args['visibility']);?></div><div class="col-md-1"><button class="btn btn-outline-primary w-100" type="submit"><?php esc_html_e('Filter','projectpress');?></button></div></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th><?php esc_html_e('Project','projectpress');?></th><th><?php esc_html_e('Key','projectpress');?></th><th><?php esc_html_e('Status','projectpress');?></th><th><?php esc_html_e('Priority','projectpress');?></th><th><?php esc_html_e('Visibility','projectpress');?></th></tr></thead><tbody><?php if(empty($projects)):?><tr><td colspan="5"><?php esc_html_e('No projects found.','projectpress');?></td></tr><?php endif;foreach($projects as $project):$edit=admin_url('admin.php?page=projectpress&group=project-manager&tab=edit&project_id='.$project->get_id());?><tr><td><a href="<?php echo esc_url($edit);?>"><?php echo esc_html($project->get_name());?></a></td><td><?php echo esc_html($project->get_key());?></td><td><?php echo esc_html($project->get_status());?></td><td><?php echo esc_html($project->get_priority());?></td><td><?php echo esc_html($project->get_visibility());?></td></tr><?php endforeach;?></tbody></table></div><?php }
 public function render_form(int $project_id=0):void{$project=$project_id>0?$this->manager->find($project_id):null;if($project_id>0&&!$project){echo '<div class="notice notice-error"><p>'.esc_html__('Project not found.','projectpress').'</p></div>';return;}$data=$project?$project->to_array():array('name'=>'','description'=>'','status'=>Defaults::PROJECT_STATUS_DEFAULT,'priority'=>Defaults::PROJECT_PRIORITY_DEFAULT,'visibility'=>Defaults::PROJECT_VISIBILITY_DEFAULT);?><form class="card card-body" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_project_save"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project_id);?>"/><?php wp_nonce_field('projectpress_project_save');?><div class="mb-3"><?php echo FormFieldHelper::label('project-name',__('Name','projectpress'));echo FormFieldHelper::text_input('name',(string)$data['name'],array('id'=>'project-name','required'=>true));?></div><div class="mb-3"><?php echo FormFieldHelper::label('project-description',__('Description','projectpress'));echo FormFieldHelper::textarea('description',(string)$data['description'],array('id'=>'project-description','rows'=>5));?></div><div class="row g-3"><div class="col-md-4"><?php echo FormFieldHelper::select('status',array_combine(Defaults::project_statuses(),Defaults::project_statuses()),$data['status']);?></div><div class="col-md-4"><?php echo FormFieldHelper::select('priority',array_combine(Defaults::project_priorities(),Defaults::project_priorities()),$data['priority']);?></div><div class="col-md-4"><?php echo FormFieldHelper::select('visibility',array_combine(Defaults::project_visibilities(),Defaults::project_visibilities()),$data['visibility']);?></div></div><hr/><div class="row g-3"><?php foreach($this->classification_map() as $field=>$definition):$terms=$this->classifications->terms($definition['taxonomy']);$selected=$project?$this->classifications->assigned_term_ids($project_id,$definition['taxonomy']):array();?><div class="col-md-6"><label class="form-label" for="<?php echo esc_attr($field);?>"><?php echo esc_html($definition['label']);?></label><select class="form-select" id="<?php echo esc_attr($field);?>" name="<?php echo esc_attr($field);?>[]" multiple><?php foreach($terms as $term):?><option value="<?php echo esc_attr((string)$term->term_id);?>" <?php selected(in_array((int)$term->term_id,$selected,true));?>><?php echo esc_html($term->name);?></option><?php endforeach;?></select></div><?php endforeach;?></div><button class="btn btn-primary mt-3" type="submit"><?php echo esc_html($project?__('Update Project','projectpress'):__('Create Project','projectpress'));?></button></form><?php }
 public function handle_save():void{check_admin_referer('projectpress_project_save');$id=RequestHelper::integer($_POST,'project_id',0);$input=array('name'=>RequestHelper::text($_POST,'name',''),'description'=>RequestHelper::text($_POST,'description',''),'status'=>RequestHelper::key($_POST,'status',Defaults::PROJECT_STATUS_DEFAULT),'priority'=>RequestHelper::key($_POST,'priority',Defaults::PROJECT_PRIORITY_DEFAULT),'visibility'=>RequestHelper::key($_POST,'visibility',Defaults::PROJECT_VISIBILITY_DEFAULT));$result=$id>0?(($project=$this->manager->find($id))?$this->manager->service()->update($project,$input):new \WP_Error('projectpress_project_not_found',__('Project not found.','projectpress'))):$this->manager->create($input);if(!is_wp_error($result)&&$result instanceof Project){foreach($this->classification_map() as $field=>$definition){$ids=array_map('absint',RequestHelper::array($_POST,$field,array()));$this->classifications->assign($result->get_id(),$definition['taxonomy'],$ids);}}$this->redirect_result($result);}
 public function handle_delete():void{check_admin_referer('projectpress_project_delete');$id=RequestHelper::integer($_POST,'project_id',0);$project=$this->manager->find($id);$this->redirect_result($project?$this->manager->service()->delete($project):new \WP_Error('projectpress_project_not_found',__('Project not found.','projectpress')));}
 public function handle_bulk():void{$this->redirect_result(new \WP_Error('projectpress_bulk_unavailable',__('Bulk deletion is disabled while the project archive lifecycle is implemented.','projectpress')));}
 private function classification_map():array{return array('project_types'=>array('taxonomy'=>Taxonomies::PROJECT_TYPE,'label'=>__('Types','projectpress')),'project_categories'=>array('taxonomy'=>Taxonomies::PROJECT_CATEGORY,'label'=>__('Categories','projectpress')),'project_tags'=>array('taxonomy'=>Taxonomies::PROJECT_TAG,'label'=>__('Tags','projectpress')),'project_labels'=>array('taxonomy'=>Taxonomies::PROJECT_LABEL,'label'=>__('Labels','projectpress')));}
 private function redirect_result($result):void{$url=admin_url('admin.php?page=projectpress&group=project-manager&tab=projects');$url=is_wp_error($result)?add_query_arg('project_error',rawurlencode($result->get_error_message()),$url):add_query_arg('project_saved','1',$url);wp_safe_redirect($url);exit;}
}
